import { MOBILE_COLS_NUMBER, TABLET_COLS_NUMBER } from "./constants";
// eslint-disable-next-line complexity
export const fillGridState = (gridState) => {
    const { lg, md, sm } = gridState;
    // If no values provided
    if (!lg && !md && !sm) {
        return;
    }
    // If all values provided
    if (lg && md && sm) {
        return;
    }
    // Only one value provided
    if (lg && !md && !sm) {
        gridState.md = lg > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : lg;
        gridState.sm = lg > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : lg;
        return;
    }
    if (md && !lg && !sm) {
        gridState.lg = md;
        gridState.sm = md > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : md;
        return;
    }
    if (sm && !lg && !md) {
        gridState.lg = sm;
        gridState.md = sm;
        return;
    }
    // If two values provided
    if (lg && md && !sm) {
        gridState.sm = md > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : md;
        return;
    }
    if (lg && sm && !md) {
        gridState.md = lg > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : lg;
        return;
    }
    if (md && sm && !lg) {
        gridState.lg = md;
        return;
    }
};
